"""Tests for metrics.counters (hits)."""

from metrics.counters import Metrics  # noqa: F401
import pytest


class TestMetrics:
    @pytest.fixture(autouse=True)
    def reset_hits(self):
        before = Metrics.hits
        yield
        Metrics.hits = before

    def test_record_hit_increments(self):
        before = Metrics.hits
        Metrics.record_hit()
        assert Metrics.hits == before + 1

